//! The bundled registry data: `src/data/*.json`, generated by
//! `scripts/build-data.mjs` from mzizi-registry at the ref pinned in
//! `scripts/registry-ref.json`, the same files the TypeScript Worker bundles.
//! Nothing is fetched at request time and nothing comes from a database.
//!
//! `build.rs` packs the files so a cold isolate parses only what a request
//! reads: a keyed lookup (one component, its source, a skill, a changelog
//! version) parses that one value, and a whole-file read (the index, the
//! helix, the brand) parses only that route's file, once per isolate.

use std::collections::HashMap;
use std::sync::OnceLock;

use indexmap::IndexMap;
use mzizi_api_types::{AstroDocument, ComponentDocs, Helix, ItemFile, Object, RegistryItem};
use serde::Deserialize;
use serde::de::DeserializeOwned;
use serde_json::Value;

/// JSON values in one blob, found by key.
pub struct Packed {
    blob: &'static str,
    /// `(key, start, end)`, sorted by key.
    index: &'static [(&'static str, usize, usize)],
}

impl Packed {
    /// The JSON text of `key`'s value.
    pub fn raw(&self, key: &str) -> Option<&'static str> {
        let i = self
            .index
            .binary_search_by(|(k, _, _)| (*k).cmp(key))
            .ok()?;
        let (_, start, end) = self.index[i];
        Some(&self.blob[start..end])
    }

    /// `key`'s value, parsed.
    pub fn get<T: DeserializeOwned>(&self, key: &str) -> Option<T> {
        let raw = self.raw(key)?;
        Some(serde_json::from_str(raw).unwrap_or_else(|e| panic!("bundled {key}: {e}")))
    }

    /// Every key, sorted by bytes.
    pub fn keys(&self) -> impl Iterator<Item = &'static str> {
        self.index.iter().map(|(k, _, _)| *k)
    }
}

mod bundle {
    use super::Packed;
    include!(concat!(env!("OUT_DIR"), "/bundle.rs"));
}

pub use bundle::{COMPONENT_COUNT, CRATE_GIT, OPENAPI_YAML, REGISTRY_REF};

macro_rules! data_file {
    ($file:literal) => {
        include_str!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../src/data/",
            $file
        ))
    };
}

macro_rules! out_file {
    ($file:literal) => {
        include_str!(concat!(env!("OUT_DIR"), "/", $file))
    };
}

fn parse<T: DeserializeOwned>(file: &str, text: &str) -> T {
    serde_json::from_str(text).unwrap_or_else(|e| panic!("{file}: {e}"))
}

macro_rules! lazy {
    ($(#[$m:meta])* $name:ident: $ty:ty = $text:expr, $file:literal) => {
        $(#[$m])*
        pub fn $name() -> &'static $ty {
            static CELL: OnceLock<$ty> = OnceLock::new();
            CELL.get_or_init(|| parse($file, $text))
        }
    };
}

/// One entry of `sources.json`: the item's primary source and its `.rs`.
#[derive(Debug, Deserialize)]
pub struct SourcePair {
    pub primary: Option<String>,
    pub rs: Option<String>,
}

/// `helix.json`.
#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct HelixFile {
    pub model: Helix,
    pub node_counts: Object,
}

/// `skills.json` without the skill bodies (those are looked up one at a time).
#[derive(Debug, Deserialize)]
pub struct SkillsList {
    pub list: Vec<Value>,
    pub names: Vec<String>,
    pub version: Value,
}

lazy!(
    /// Every registry item, in registry order, with the fields the index and
    /// search serve (`name`, `type`, `title`, `description`, `categories`,
    /// dependencies, `node`, `nodeLabel`, `meta.owner`, `meta.collection`,
    /// `rsPath`). The full item is [`read_component`].
    components: Vec<RegistryItem> = out_file!("components-index.json"), "components.json"
);
lazy!(helix: HelixFile = data_file!("helix.json"), "helix.json");
lazy!(
    /// `changelog.json` `entries`.
    changelog_entries: Vec<Value> = out_file!("changelog-entries.json"), "changelog.json"
);
lazy!(doctrine: Object = data_file!("doctrine.json"), "doctrine.json");
lazy!(skills: SkillsList = out_file!("skills-list.json"), "skills.json");
lazy!(
    /// Sample records by type, in the file's order (`Object.keys` order).
    samples: IndexMap<String, Vec<Value>> = data_file!("samples.json"), "samples.json"
);
lazy!(brand: Object = data_file!("brand.json"), "brand.json");
lazy!(
    ai_instruction_index: HashMap<String, usize> = data_file!("ai-instruction-index.json"),
    "ai-instruction-index.json"
);

/// The `mzizi-*` name a `nyuchi-*` component was renamed to
/// (mzizi-registry lib/component-renames.json).
pub fn renamed(name: &str) -> Option<&'static str> {
    let i = bundle::RENAMES
        .binary_search_by(|(k, _)| (*k).cmp(name))
        .ok()?;
    Some(bundle::RENAMES[i].1)
}

/// lib/registry.ts `readComponent`: by name, then by the name it was renamed
/// from. The full item, `meta` block and all.
pub fn read_component(name: &str) -> Option<RegistryItem> {
    bundle::ITEMS
        .get(name)
        .or_else(|| bundle::ITEMS.get(renamed(name)?))
}

/// Which source of an item.
#[derive(Debug, Clone, Copy)]
pub enum SourceKind {
    Primary,
    Rs,
}

/// lib/registry-source.ts `readComponentSource` / `readComponentSourceFor(name, "rs")`.
pub fn read_source(name: &str, kind: SourceKind) -> Option<String> {
    let pair: SourcePair = bundle::SOURCES.get(name)?;
    match kind {
        SourceKind::Primary => pair.primary,
        SourceKind::Rs => pair.rs,
    }
}

/// The base64 files of a binary-only item.
pub fn read_binary(name: &str) -> Option<Vec<ItemFile>> {
    bundle::BINARY.get(name)
}

/// mzizi-registry lib/astro.ts `astroDocument(name)`, resolved at build time.
pub fn read_astro(name: &str) -> Option<AstroDocument> {
    bundle::ASTRO.get(name)
}

/// Every name `/v1/astro/{name}` serves, sorted as JS sorts (UTF-16 code units).
pub fn astro_names() -> Vec<&'static str> {
    let mut names: Vec<&'static str> = bundle::ASTRO.keys().collect();
    names.sort_by(|a, b| a.encode_utf16().cmp(b.encode_utf16()));
    names
}

/// lib/db `getComponentWithDocs(name)`: the docs row and demo flag.
pub fn read_component_docs(name: &str) -> Option<ComponentDocs> {
    bundle::COMPONENT_DOCS.get(name)
}

/// `changelog.json` `byVersion[version]`.
pub fn read_changelog_version(version: &str) -> Option<Vec<Value>> {
    bundle::CHANGELOG_VERSIONS.get(version)
}

/// `skills.json` `byName[name]`.
pub fn read_skill(name: &str) -> Option<Value> {
    bundle::SKILLS.get(name)
}

/// lib/db `getAiInstruction(key) ?? getAiInstructionByTarget(key)`.
pub fn read_ai_instruction(key: &str) -> Option<&'static Value> {
    let index = *ai_instruction_index().get(key)?;
    doctrine().get("aiInstructions")?.as_array()?.get(index)
}

/// `X-Mzizi-Source`: identifies this Worker's answers and the registry commit.
pub fn source_header() -> &'static str {
    static CELL: OnceLock<String> = OnceLock::new();
    CELL.get_or_init(|| {
        let short: String = REGISTRY_REF.chars().take(12).collect();
        format!("mzizi-api-gateway; registry={short}")
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    /// `Packed::get` panics on a value that does not deserialise, and a panic
    /// aborts the isolate (a headerless Cloudflare 1101). Every key of every
    /// table, and every whole file, must parse into the type it is read as.
    #[test]
    fn every_bundled_value_deserialises_into_its_type() {
        fn all<T: DeserializeOwned>(table: &Packed, what: &str) -> usize {
            let mut n = 0;
            for key in table.keys() {
                let raw = table.raw(key).unwrap();
                if let Err(e) = serde_json::from_str::<T>(raw) {
                    panic!("{what}[{key}]: {e}");
                }
                n += 1;
            }
            n
        }
        assert_eq!(
            all::<RegistryItem>(&bundle::ITEMS, "items"),
            COMPONENT_COUNT
        );
        assert!(all::<SourcePair>(&bundle::SOURCES, "sources") > 0);
        assert!(all::<Vec<ItemFile>>(&bundle::BINARY, "binary") > 0);
        assert!(all::<AstroDocument>(&bundle::ASTRO, "astro") > 0);
        assert!(all::<ComponentDocs>(&bundle::COMPONENT_DOCS, "component-docs") > 0);
        assert!(all::<Vec<Value>>(&bundle::CHANGELOG_VERSIONS, "changelog versions") > 0);
        assert!(all::<Value>(&bundle::SKILLS, "skills") > 0);
        // The whole files, through the same lazy readers the routes use.
        components();
        helix();
        changelog_entries();
        doctrine();
        skills();
        samples();
        brand();
        ai_instruction_index();
        // The tables are sorted, so the binary search finds every key.
        for table in [
            &bundle::ITEMS,
            &bundle::SOURCES,
            &bundle::BINARY,
            &bundle::ASTRO,
            &bundle::COMPONENT_DOCS,
            &bundle::CHANGELOG_VERSIONS,
            &bundle::SKILLS,
        ] {
            assert!(table.index.windows(2).all(|w| w[0].0 < w[1].0));
            assert!(table.keys().all(|k| table.raw(k).is_some()));
        }
        assert!(bundle::RENAMES.windows(2).all(|w| w[0].0 < w[1].0));
    }

    #[test]
    fn packed_lookups_match_the_index() {
        assert_eq!(components().len(), COMPONENT_COUNT);
        for item in components() {
            let full = read_component(&item.name).expect(&item.name);
            assert_eq!(full.name, item.name);
            assert_eq!(full.description, item.description);
            assert_eq!(full.node, item.node);
        }
        assert!(read_component("does-not-exist").is_none());
        assert!(read_source("button", SourceKind::Primary).is_some());
    }
}
